//! Explicit client identity/dispatch; does not enable production default.
use std::process::Command;
#[test]fn explicit_client_v2_identity_needs_no_compiler_or_workspace(){let output=Command::new(env!("CARGO_BIN_EXE_analyze-native")).arg("--client-version").env("DQ_DMBC_BIN","must-not-be-read").output().unwrap();assert!(output.status.success());assert_eq!(output.stdout,b"native-analyze-client-v2\n");assert!(output.stderr.is_empty());}
#[test]fn explicit_utility_dispatch_precedes_generic_sem_without_launching_a_compiler(){let absent=if cfg!(windows){"E:/absent-must-not-run/dmbc.exe"}else{"/absent-must-not-run/dmbc"};let list=Command::new(env!("CARGO_BIN_EXE_analyze-native")).args(["codemod","list","--native-dmbc",absent]).output().unwrap();assert!(list.status.success());assert!(!list.stdout.is_empty());for(args,expected)in[(vec!["sem","fixture","--native-dmbc",absent],"usage: analyze sem fixture LINT [--bless]"),(vec!["parity","--fixtures-only","--native-dmbc",absent],"analyze parity: name a lint or pass --all")]{let output=Command::new(env!("CARGO_BIN_EXE_analyze-native")).args(args).output().unwrap();assert_eq!(output.status.code(),Some(2));assert!(output.stdout.is_empty());assert!(String::from_utf8_lossy(&output.stderr).contains(expected));}}
